# WARNING: Under review - generated by LLM.


import pytest

from .tiny_llm_base import AgentError, ToolAction, ToolPolicy, Workspace


def test_task_1_lists_and_reads_bounded_workspace_files(tmp_path):
    (tmp_path / "README.md").write_text("hello", encoding="utf-8")
    (tmp_path / ".env").write_text("SECRET=value", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path))

    listing = workspace.list_files()
    assert "file README.md" in listing
    assert ".env" not in listing
    assert workspace.read_file("README.md") == "hello"


def test_task_1_list_is_sorted_and_bounded(tmp_path):
    for name in ("c.txt", "a.txt", "b.txt"):
        (tmp_path / name).write_text(name, encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, max_list_entries=2))

    assert workspace.list_files().splitlines() == ["file a.txt", "file b.txt"]


def test_task_1_rejects_oversized_non_utf8_and_non_file_reads(tmp_path):
    (tmp_path / "large.txt").write_text("12345", encoding="utf-8")
    (tmp_path / "binary.dat").write_bytes(b"\xff")
    (tmp_path / "directory").mkdir()
    workspace = Workspace(ToolPolicy(tmp_path, max_file_bytes=4))

    with pytest.raises(AgentError, match="exceeds 4 bytes"):
        workspace.read_file("large.txt")
    assert workspace.execute(
        ToolAction("read_file", {"path": "binary.dat"})
    ).startswith("error:")


@pytest.mark.parametrize(
    "path",
    [
        "../outside.txt",
        "/etc/passwd",
        "a/../../outside.txt",
        ".git/config",
        "secret.pem",
        ".env.local",
    ],
)
def test_task_2_rejects_unsafe_paths(tmp_path, path):
    (tmp_path / "outside.txt").write_text("x", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path))

    with pytest.raises(AgentError):
        workspace.read_file(path)


def test_task_2_rejects_symlinks(tmp_path):
    (tmp_path / "real.txt").write_text("real", encoding="utf-8")
    (tmp_path / "link.txt").symlink_to(tmp_path / "real.txt")
    workspace = Workspace(ToolPolicy(tmp_path))

    with pytest.raises(AgentError):
        workspace.read_file("link.txt")
    result = workspace.execute(ToolAction("read_file", {"path": "link.txt"}))
    assert result.startswith("error:")


def test_task_3_writes_are_disabled_by_default(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path))

    with pytest.raises(AgentError, match="disabled"):
        workspace.write_file("new.txt", "data")
    assert not (tmp_path / "new.txt").exists()


def test_task_3_creates_and_atomically_replaces_files(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))

    assert workspace.write_file("new.txt", "one") == "wrote new.txt"
    assert (tmp_path / "new.txt").read_text(encoding="utf-8") == "one"
    assert workspace.write_file("new.txt", "two") == "wrote new.txt"
    assert (tmp_path / "new.txt").read_text(encoding="utf-8") == "two"


def test_task_3_requires_inspection_before_overwriting(tmp_path):
    (tmp_path / "existing.txt").write_text("old", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))

    with pytest.raises(AgentError, match="must be read"):
        workspace.write_file("existing.txt", "new")
    assert (tmp_path / "existing.txt").read_text(encoding="utf-8") == "old"


def test_task_3_rejects_a_stale_observation_before_confirmation(tmp_path):
    path = tmp_path / "answer.py"
    path.write_text("ANSWER = 41\n", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))
    workspace.read_file("answer.py")
    path.write_text("ANSWER = 42\n", encoding="utf-8")

    with pytest.raises(AgentError, match="changed since"):
        workspace.write_file("answer.py", "ANSWER = 43\n")


def test_task_3_edit_requires_one_exact_match(tmp_path):
    path = tmp_path / "example.py"
    path.write_text("answer = 41\n", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))
    workspace.read_file("example.py")

    workspace.edit_file("example.py", "41", "42")

    assert path.read_text(encoding="utf-8") == "answer = 42\n"
    assert workspace.modified_files == {path}


def test_task_3_model_dispatched_writes_are_denied_without_confirmation(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))

    result = workspace.execute(
        ToolAction("write_file", {"path": "new.txt", "content": "data"})
    )

    assert result == "error: operator denied write_file"
    assert not (tmp_path / "new.txt").exists()


def test_task_3_model_dispatched_mutations_prompt_exactly_once(tmp_path):
    path = tmp_path / "answer.py"
    path.write_text("ANSWER = 41\n", encoding="utf-8")
    confirmations = []
    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=lambda action: confirmations.append(action.tool) or True,
    )
    workspace.read_file("answer.py")

    result = workspace.execute(
        ToolAction("edit_file", {"path": "answer.py", "old": "41", "new": "42"})
    )

    assert result == "wrote answer.py"
    assert confirmations == ["edit_file"]
    assert path.read_text(encoding="utf-8") == "ANSWER = 42\n"


