def test_task_3_commands_require_an_exact_operator_allowlist(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path, allowed_commands=(("echo", "ok"),)))

    with pytest.raises(AgentError, match="not explicitly allowed"):
        workspace.run_command(["some-command"])


def test_task_3_unallowlisted_command_is_rejected_before_confirmation(tmp_path):
    confirmations = []
    workspace = Workspace(
        ToolPolicy(tmp_path, allowed_commands=(("echo", "ok"),)),
        confirm_tool=lambda action: confirmations.append(action) or True,
    )

    result = workspace.execute(ToolAction("run_command", {"argv": ["rm", "-rf", "."]}))

