def test_task_3_denied_command_never_starts_a_process(tmp_path):
    confirmations = []
    workspace = Workspace(
        ToolPolicy(tmp_path, allowed_commands=(("echo", "ok"),)),
        confirm_tool=lambda action: confirmations.append(action.tool) or False,
    )

    result = workspace.execute(ToolAction("run_command", {"argv": ["echo", "ok"]}))

    assert result == "error: operator denied run_command"
    assert confirmations == ["run_command"]


def test_task_3_allowed_command_runs_with_confirmation(tmp_path):
    workspace = Workspace(
        ToolPolicy(tmp_path, allowed_commands=(("echo", "ok"),)),
        confirm_tool=lambda action: True,
    )

    result = workspace.execute(ToolAction("run_command", {"argv": ["echo", "ok"]}))

    assert "ok" in result
    assert not result.startswith("error:")
